<?php require __DIR__.'/bootstrap.php';$u=require_login();$q=$pdo->query("SELECT m.id,m.message,m.created_at,u.name,u.role FROM community_messages m JOIN users u ON u.id=m.user_id WHERE m.status='visible' ORDER BY m.id DESC LIMIT 50");$messages=array_reverse($q->fetchAll());?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comunidade — Arena de Aço</title><link rel="stylesheet" href="assets/app.css"></head><body class="anime"><?php nav($u)?><main class="community"><header class="community-head"><div><p class="eyebrow">COMUNIDADE ARENA</p><h1>Converse com a galera.</h1><p class="muted">Um espaço para leitores, criadores e apoiadores compartilharem teorias, novidades e descobertas.</p></div><span class="live-dot">● AO VIVO</span></header><section class="chatbox"><div class="chat-title"><b>💬 Chat geral</b><small>Respeite a comunidade</small></div><div id="messages" class="messages"><?php foreach($messages as $m):?><article class="chat-message" data-id="<?=$m['id']?>"><div class="chat-avatar"><?=e(mb_strtoupper(mb_substr($m['name'],0,1)))?></div><div><b><?=e($m['name'])?> <?php if($m['role']!=='member'):?><small class="staff">EQUIPE</small><?php endif?></b><time><?=date('H:i',strtotime($m['created_at']))?></time><p><?=nl2br(e($m['message']))?></p></div></article><?php endforeach?></div><form id="chat-form" class="chat-form"><input id="chat-input" name="message" maxlength="1000" placeholder="Escreva uma mensagem para a comunidade..." autocomplete="off"><button class="redbtn">Enviar</button></form></section></main><script>let last=[...document.querySelectorAll('.chat-message')].reduce((n,e)=>Math.max(n,+e.dataset.id),0);const box=document.querySelector('#messages'),form=document.querySelector('#chat-form'),input=document.querySelector('#chat-input');function draw(list){list.forEach(m=>{last=Math.max(last,+m.id);const el=document.createElement('article');el.className='chat-message';el.dataset.id=m.id;el.innerHTML='<div class="chat-avatar">'+m.name.charAt(0).toUpperCase()+'</div><div><b>'+esc(m.name)+(m.role!=='member'?' <small class="staff">EQUIPE</small>':'')+'</b><time>'+new Date(m.created_at.replace(' ','T')).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})+'</time><p>'+esc(m.message).replace(/\n/g,'<br>')+'</p></div>';box.append(el);box.scrollTop=box.scrollHeight;});}function esc(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}form.onsubmit=async e=>{e.preventDefault();if(!input.value.trim())return;const f=new FormData();f.append('message',input.value);const r=await fetch('chat_api.php',{method:'POST',body:f});if(r.ok){input.value='';poll();}};async function poll(){const r=await fetch('chat_api.php?after='+last);if(r.ok)draw((await r.json()).messages||[]);}setInterval(poll,4000);box.scrollTop=box.scrollHeight;</script></body></html>
